import * as React from "react";

export interface BentoMetricCard {
  label: string;
  value: string;
  trend?: string;
  description?: string;
  span?: 1 | 2 | 3;
}

export interface BentoGridMetricsProps {
  cards?: BentoMetricCard[];
  className?: string;
}

const DEFAULTS: BentoMetricCard[] = [
  {
    label: "Sync speed",
    value: "99.9% uptime",
    description: "Synchronized database instances across 6 AWS clusters.",
    span: 2,
  },
  {
    label: "SaaS Yield",
    value: "+48.2%",
    trend: "vs last quarter",
  },
  {
    label: "Studio",
    value: "Fully custom interactive studio controls",
    span: 3,
  },
];

/**
 * BentoGridMetrics — responsive 3-column metrics grid that collapses to a
 * single column on mobile. Each card supports a span hint so editors can
 * highlight a flagship metric.
 */
export function BentoGridMetrics({
  cards = DEFAULTS,
  className,
}: BentoGridMetricsProps) {
  return (
    <div
      className={[
        "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 w-full",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {cards.map((card, idx) => (
        <div
          key={idx}
          className={[
            "p-5 rounded-2xl border border-border bg-card space-y-1.5",
            card.span === 2 ? "sm:col-span-2" : "",
            card.span === 3 ? "sm:col-span-2 md:col-span-3" : "",
          ]
            .filter(Boolean)
            .join(" ")}
        >
          <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-[0.16em]">
            {card.label}
          </span>
          <h3 className="text-base font-extrabold text-foreground">
            {card.value}
          </h3>
          {card.trend ? (
            <span className="text-[10px] font-bold text-emerald-500">
              {card.trend}
            </span>
          ) : null}
          {card.description ? (
            <p className="text-xs text-muted-foreground">{card.description}</p>
          ) : null}
        </div>
      ))}
    </div>
  );
}

export default BentoGridMetrics;
